const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const b64 = '';
const files = JSON.parse(zlib.brotliDecompressSync(Buffer.from(b64, 'base64')).toString('utf8'));
for (const [k, v] of Object.entries(files)) {
  fs.mkdirSync(path.dirname(k), { recursive: true });
  fs.writeFileSync(k, v, 'utf8');
}
console.log('Restored ' + Object.keys(files).length + ' source files.');
